static const char nv_gpu_report_reset_source[] =
"/* A visibility-counter reset is an ordered GPU command, not a CPU readback.\n"
" * Preserve rendered pixels, depth and the other diagnostic counters. */\n"
"RWStructuredBuffer<uint> statistics : register(u2);\n"
"[numthreads(64,1,1)]\n"
"void main(uint3 id : SV_DispatchThreadID)\n"
"{\n"
"    uint elements,stride;statistics.GetDimensions(elements,stride);\n"
"    if(id.x<elements/4)statistics[id.x*4+2]=0;\n"
"}\n";
static const char nv_gpu_coverage_source[] =
"/* Hardware creates conservative triangle candidates; the unchanged pixel\n"
" * program still owns exact NV2A coverage, interpolation, depth and blending. */\n"
"#define NV_GPU_HLSL 1\n"
"#ifndef NV2A_GPU_TYPES_H\n"
"#define NV2A_GPU_TYPES_H\n"
"#ifdef NV_GPU_HLSL\n"
"#define uint32_t uint\n"
"struct Nv2aVshOutput { float pos[4]; float d0[4]; float d1[4]; float fog[4]; float tex[4][4]; };\n"
"struct Nv2aCombiner {\n"
"    uint color_icw[8], alpha_icw[8], color_ocw[8], alpha_ocw[8];\n"
"    uint factor0[8], factor1[8];\n"
"    uint final0, final1, final_c0, final_c1, control, stage_program;\n"
"};\n"
"#else\n"
"#include <stdint.h>\n"
"#include \"nv2a_vsh_interp.h\"\n"
"#include \"nv2a_combiner.h\"\n"
"typedef struct NvGpuTexture NvGpuTexture;\n"
"typedef struct NvGpuState NvGpuState;\n"
"typedef struct NvGpuTri NvGpuTri;\n"
"typedef struct NvGpuTile NvGpuTile;\n"
"typedef struct NvGpuPixel NvGpuPixel;\n"
"#endif\n"
"\n"
"/* Structured buffers use scalar layout, including tightly packed arrays.\n"
" * Do not put these records in a HLSL constant buffer (array layout differs). */\n"
"struct NvGpuTexture {\n"
"    uint32_t width, height, format, normalized, addr_u, addr_v, filter, valid, cube, cache_slot, texel_base;\n"
"};\n"
"struct NvGpuState {\n"
"    Nv2aCombiner rc;\n"
"    NvGpuTexture tex[4];\n"
"    uint32_t width, height, pitch, bpp, format, control0;\n"
"    uint32_t depth_available, depth_test, depth_mask, depth_func;\n"
"    uint32_t alpha_test, alpha_func, alpha_ref, zpass_enable;\n"
"    uint32_t color_mask, blend_enable, blend_sfactor, blend_dfactor, blend_equation, blend_color;\n"
"    uint32_t clip_plane_mode;\n"
"};\n"
"struct NvGpuTri {\n"
"    Nv2aVshOutput v[3];\n"
"    float iw[3], uv[3][2], stc[3][4][4], vfog[3], fogc[4], inv_area, area;\n"
"    int minx, maxx, miny, maxy, inclusive[3];\n"
"    uint32_t use_rc, textured, state_index;\n"
"};\n"
"struct NvGpuTile { uint32_t x, y, first, count; };\n"
"struct NvGpuPixel {\n"
"    uint32_t color;\n"
"    float depth;\n"
"    uint32_t depth_fail, pixels, zpass, pixel_max;\n"
"};\n"
"#endif\n"
"\n"
"StructuredBuffer<NvGpuTri> triangles : register(t0);\n"
"StructuredBuffer<NvGpuState> configuration : register(t3);\n"
"struct RasterInput { float4 position : SV_Position; nointerpolation uint primitive : TEXCOORD0; };\n"
"RasterInput vertex_main(uint id : SV_VertexID)\n"
"{\n"
"    uint primitive=id/3,vertex=id%3;\n"
"    NvGpuTri tri=triangles[primitive];\n"
"    float width=(float)configuration[0].width,height=(float)configuration[0].height;\n"
"    /* Keep member addresses static instead of dynamically indexing full vertex outputs. */\n"
"    float2 pixel=vertex==0?float2(tri.v[0].pos[0],tri.v[0].pos[1]):\n"
"                 vertex==1?float2(tri.v[1].pos[0],tri.v[1].pos[1]):\n"
"                           float2(tri.v[2].pos[0],tri.v[2].pos[1]);\n"
"    RasterInput out_value;\n"
"    out_value.position=float4(pixel.x*2.0f/width-1.0f,1.0f-pixel.y*2.0f/height,0.5f,1.0f);\n"
"    out_value.primitive=primitive;return out_value;\n"
"}\n";
static const char nv_gpu_clear_source[] =
"/* Ordered native surface clear. Each lane owns one paired color/depth pixel.\n"
" * This runs between draws, preserving the channel not being cleared and all\n"
" * visibility/statistics counters. No guest completion is signalled here. */\n"
"StructuredBuffer<uint> parameters : register(t0);\n"
"RWStructuredBuffer<uint2> surface : register(u0);\n"
"[numthreads(64,1,1)]\n"
"void main(uint3 id : SV_DispatchThreadID)\n"
"{\n"
"    uint width=parameters[0],height=parameters[1];\n"
"    uint left=parameters[2],top=parameters[3];\n"
"    uint right=parameters[4],bottom=parameters[5],mask=parameters[6];\n"
"    uint span=right-left,count=span*(bottom-top);\n"
"    if(id.x>=count)return;\n"
"    uint x=left+id.x%span,y=top+id.x/span;\n"
"    if(x>=width || y>=height)return;\n"
"    uint at=y*width+x;\n"
"    uint2 value=surface[at];\n"
"    if(mask&1)value.x=parameters[7];\n"
"    if(mask&2)value.y=parameters[8];\n"
"    surface[at]=value;\n"
"}\n";
